window.CFA_FORMULAS=[{"id":"quant","name":"Quantitative Methods","sections":[{"h":"Rates and Returns","items":[{"t":"Required Rate of Return","f":"\\text{Interest rate} = \\text{Real risk-free rate} + \\text{Inflation premium} + \\text{Default risk premium} + \\text{Liquidity premium} + \\text{Maturity premium}"},{"t":"Nominal risk-free rate","f":"(1+\\text{Nominal risk-free rate}) = (1+\\text{Real risk-free rate})(1+\\text{Inflation premium})"},{"t":"Nominal risk-free rate (approx.)","f":"\\text{Nominal risk-free rate} \\approx \\text{Real risk-free rate} + \\text{Inflation premium}"},{"t":"Holding Period Return","f":"R = \\dfrac{P_1 - P_0 + I_1}{P_0}"},{"t":"Holding Period Return (multi-period)","f":"R = [(1+R_1)(1+R_2)\\cdots(1+R_n)] - 1"},{"t":"Arithmetic Mean Return","f":"\\bar{R}_i = \\dfrac{\\sum_{t=1}^{T} R_{it}}{T}"},{"t":"Geometric Mean Return","f":"\\bar{R}_{Gi} = \\sqrt[T]{\\prod_{t=1}^{T}(1+R_{it})} - 1"},{"t":"Harmonic Mean Return (Cost Averaging)","f":"\\bar{X}_H = \\dfrac{n}{\\sum_{i=1}^{n} \\frac{1}{X_i}}, \\quad X_i > 0","n":"If returns are volatile: X̄(arithmetic) ≥ X̄(geometric) ≥ X̄(harmonic)."},{"t":"Money-Weighted Return (MWR)","n":"IRR derived from all cash inflows and returns. Can be skewed by timing/value of cash flows. Appropriate if manager controls timing of cash flows."},{"t":"Time-Weighted Return (TWR)","n":"Geometric mean of sub-period returns. Compound growth for an initial $1 investment. Unaffected by timing/value of cash flows."}]},{"h":"The Time Value of Money","items":[{"t":"Future Value & Present Value","f":"FV_N = PV(1+r)^N \\qquad PV = FV_N(1+r)^{-N}"},{"t":"FV & PV with periodic compounding","f":"FV_N = PV\\left(1+\\tfrac{r}{m}\\right)^{mN} \\qquad PV = FV_N\\left(1+\\tfrac{r}{m}\\right)^{-mN}"},{"t":"Continuously Compounded Returns","f":"FV_N = PV\\, e^{r_c N}"},{"t":"Real Returns","f":"(1+\\text{Real return}) = \\dfrac{(1+r_{rf})(1+\\text{Risk premium})}{1+\\text{Inflation premium}}"},{"t":"Leveraged Return","f":"R_L = R_P + \\dfrac{V_B}{V_E}(R_P - r_D)"}]},{"h":"Time Value of Money in Finance","items":[{"t":"Fixed-income instrument (coupon bond)","f":"PV = \\dfrac{PMT_1}{(1+r)^1} + \\dfrac{PMT_2}{(1+r)^2} + \\cdots + \\dfrac{PMT_N + FV_N}{(1+r)^N}"},{"t":"Perpetual bond / perpetuity","f":"PV = \\dfrac{PMT}{r}"},{"t":"Annuity instrument","f":"PV = A\\left[\\dfrac{1-(1+r)^{-N}}{r}\\right]"},{"t":"Equity — constant dividends","f":"PV = \\dfrac{D}{r}"},{"t":"Equity — constant dividend growth","f":"PV = \\dfrac{D_0(1+g)}{r-g} = \\dfrac{D_1}{r-g}"},{"t":"Equity — changing dividend growth","f":"PV = \\sum_{t=1}^{n}\\dfrac{D_0(1+g_s)^t}{(1+r)^t} + \\dfrac{E(S_n)}{(1+r)^n}, \\quad E(S_n)=\\dfrac{D_{n+1}}{r-g}"},{"t":"Implied return — discount bond","f":"r = \\left(\\dfrac{FV}{PV}\\right)^{1/N} - 1"},{"t":"Equity required rate of return","f":"r = \\dfrac{D_1}{PV} + g"},{"t":"Forward price-to-earnings ratio","f":"\\dfrac{PV}{E_1} = \\dfrac{D_1/E_1}{r-g}"}]},{"h":"Statistical Measures of Asset Returns","items":[{"t":"Sample mean","f":"\\bar{X} = \\dfrac{1}{n}\\sum_{i=1}^{n} X_i","n":"n = sample size"},{"t":"Median","n":"If n is odd: Median = ((n+1)/2)th term. If n is even: Median = average of the (n/2)th and (n/2 + 1)th terms."},{"t":"Mode","n":"The most frequently occurring value."},{"t":"Dealing with outliers","n":"1) No adjustments. 2) Remove all outliers with a trimmed mean. 3) Replace outliers with a winsorized mean."},{"t":"Interquartile range (IQR)","f":"IQR = Q_3 - Q_1"},{"t":"Location of the yth percentile","f":"L_y = (n+1)\\dfrac{y}{100}","n":"If L_y is not an integer, use linear interpolation. Quartiles / Quintiles / Deciles; 50th percentile = 2nd quartile = 5th decile."},{"t":"Range","f":"\\text{Range} = \\text{Maximum value} - \\text{Minimum value}"},{"t":"Mean Absolute Deviation","f":"MAD = \\dfrac{1}{n}\\sum_{i=1}^{n}|X_i - \\bar{X}|"},{"t":"Sample variance","f":"s^2 = \\dfrac{1}{n-1}\\sum_{i=1}^{n}(X_i - \\bar{X})^2","n":"Sample standard deviation is the square root of the sample variance."},{"t":"Sample target semideviation","f":"s_{target} = \\sqrt{\\dfrac{\\sum_{X_i < B}(X_i - B)^2}{n-1}}"},{"t":"Coefficient of variation","f":"CV = \\dfrac{s}{\\bar{X}}"},{"t":"Skewness","f":"\\text{Skewness} \\approx \\dfrac{1}{n}\\dfrac{\\sum_{i=1}^{n}(X_i-\\bar{X})^3}{s^3}","n":"Positive skew → mean > median (skewed right). Negative skew → mean < median (skewed left)."},{"t":"Kurtosis (Excess = Kurtosis − 3)","f":"\\text{Excess kurtosis} \\approx \\dfrac{1}{n}\\dfrac{\\sum_{i=1}^{n}(X_i-\\bar{X})^4}{s^4} - 3","n":"Leptokurtic: fatter tails, more peaked, excess > 0. Mesokurtic (normal): excess = 0. Platykurtic: thinner tails, less peaked, excess < 0."},{"t":"Sample covariance","f":"s_{XY} = \\dfrac{\\sum_{i=1}^{n}(X_i-\\bar{X})(Y_i-\\bar{Y})}{n-1}"},{"t":"Sample correlation coefficient","f":"r_{XY} = \\dfrac{s_{XY}}{s_X s_Y}"}]},{"h":"Probability Trees & Conditional Expectations","items":[{"t":"Expected value","f":"E(X) = \\sum_{i=1}^{n} P(X_i)X_i"},{"t":"Variance","f":"\\sigma^2(X) = \\sum_{i=1}^{n} P(X_i)[X_i - E(X)]^2 = E(X^2) - [E(X)]^2"},{"t":"Total probability rule for expected value","f":"E(X) = E(X|S_1)P(S_1) + \\cdots + E(X|S_n)P(S_n)"},{"t":"Conditional expected value","f":"E(X|S) = P(X_1|S)X_1 + \\cdots + P(X_n|S)X_n"},{"t":"Conditional variance","f":"\\sigma^2(X|S) = [X_1-E(X|S)]^2 P(X_1|S) + \\cdots + [X_n-E(X|S)]^2 P(X_n|S)"},{"t":"Bayes' formula","f":"P(\\text{Event}|\\text{Info}) = \\dfrac{P(\\text{Info}|\\text{Event})}{P(\\text{Info})} \\times P(\\text{Event})"}]},{"h":"Portfolio Mathematics","items":[{"t":"Expected portfolio return","f":"E(R_p) = \\sum_{i=1}^{n} w_i E(R_i)"},{"t":"Covariance of returns","f":"Cov(R_i,R_j) = E\\big[(R_i-E[R_i])(R_j-E[R_j])\\big]"},{"t":"Portfolio variance","f":"\\sigma^2(R_p) = \\sum_{i=1}^{n}\\sum_{j=1}^{n} w_i w_j Cov(R_i,R_j)","n":"An asset's covariance with itself is its variance."},{"t":"Correlation","f":"\\rho(R_i,R_j) = \\dfrac{Cov(R_i,R_j)}{\\sigma(R_i)\\sigma(R_j)}"},{"t":"Two-asset expected return","f":"E(R_p) = w_A R_A + w_B R_B"},{"t":"Two-asset covariance","f":"Cov(R_A,R_B) = \\rho(R_A,R_B)\\,\\sigma(R_A)\\sigma(R_B)"},{"t":"Two-asset portfolio variance","f":"\\sigma^2(R_p) = w_A^2\\sigma^2(R_A) + w_B^2\\sigma^2(R_B) + 2w_A w_B\\,Cov(R_A,R_B)"},{"t":"Independent variables","f":"P(XY)=P(X)P(Y) \\qquad E(XY)=E(X)E(Y)"},{"t":"Roy's safety-first ratio","f":"\\text{SFRatio} = \\dfrac{E(R_p)-R_L}{\\sigma_p}","n":"R_L = threshold level. P(R_p < R_L) = N(−SFRatio). Higher SFRatio is better."}]},{"h":"Simulation Methods","items":[{"t":"Lognormal distribution mean","f":"\\mu_L = e^{\\mu + 0.5\\sigma^2}"},{"t":"Lognormal distribution variance","f":"\\sigma_L^2 = e^{2\\mu+\\sigma^2}\\left(e^{\\sigma^2}-1\\right)","n":"μ and σ² are the mean and variance of ln(Y). If Y is lognormal, ln(Y) is normal; used to model asset prices; positively skewed."},{"t":"Continuously compounded return","f":"r_{0,T} = \\ln\\!\\left(\\dfrac{S_T}{S_0}\\right)"}]},{"h":"Estimation & Inference","items":[{"t":"Sampling methods","n":"Simple random: subset chosen at random. Systematic: every kth observation. Stratified: simple random samples from each stratum. Cluster: set divided into mini-representations. Convenience: by accessibility. Judgmental: by researcher expertise."},{"t":"Central Limit Theorem (CLT)","n":"For n ≥ 30 from a population with mean μ and variance σ², the sample mean X̄ approximately follows a normal distribution with mean μ and variance σ²/n. Sampling error = Sample mean − Population mean."},{"t":"Standard error of sample mean (σ known)","f":"\\sigma_{\\bar{X}} = \\dfrac{\\sigma}{\\sqrt{n}}"},{"t":"Standard error of sample mean (σ unknown)","f":"s_{\\bar{X}} = \\dfrac{s}{\\sqrt{n}}"},{"t":"Bootstrap vs. jackknife","n":"Bootstrap: replace each drawn sample for the next draw. Jackknife: leave out one observation at a time without replacement."}]},{"h":"Hypothesis Testing","items":[{"t":"Process of hypothesis testing","n":"1) State hypotheses. 2) Identify test statistic. 3) Specify significance level. 4) State decision rule. 5) Collect data & calculate test statistic. 6) Make decision."},{"t":"Test formulations","n":"One-tailed upper: H0 μ≤μ0, Ha μ>μ0 → reject if stat > critical value. One-tailed lower: H0 μ≥μ0, Ha μ<μ0 → reject if stat < critical value. Two-tailed: H0 μ=μ0, Ha μ≠μ0 → reject if stat < lower or > upper critical value."},{"t":"Decision errors & power","n":"Do not reject H0: correct if H0 true, Type II (β) if false. Reject H0: Type I (α) if H0 true, correct if false. Power = 1 − P(Type II error) = 1 − β. p-value = smallest α at which H0 is rejected."},{"t":"Test concerning a single mean","f":"t = \\dfrac{\\bar{X}-\\mu_0}{s/\\sqrt{n}}, \\quad df = n-1","n":"Use when sample is large (any population, unknown variance) or approximately normal."},{"t":"Difference between means (equal variances)","f":"t = \\dfrac{(\\bar{X}_1-\\bar{X}_2)-(\\mu_1-\\mu_2)}{\\sqrt{\\frac{s_p^2}{n_1}+\\frac{s_p^2}{n_2}}}, \\quad df=n_1+n_2-2"},{"t":"Pooled variance","f":"s_p^2 = \\dfrac{(n_1-1)s_1^2+(n_2-1)s_2^2}{n_1+n_2-2}"},{"t":"Test concerning mean differences (paired)","f":"t = \\dfrac{\\bar{d}-\\mu_{d0}}{s_{\\bar{d}}}, \\quad df=n-1"},{"t":"Test concerning a single variance","f":"\\chi^2 = \\dfrac{(n-1)s^2}{\\sigma_0^2}, \\quad df=n-1"},{"t":"Equality of two variances","f":"F = \\dfrac{s_1^2}{s_2^2}, \\quad df_1=n_1-1,\\; df_2=n_2-1"},{"t":"Nonparametric tests","n":"Used when concerned with a parameter, when data assumptions fail, when data are ordinal/ranked, or when the hypothesis does not concern a parameter."}]},{"h":"Tests of Independence","items":[{"t":"Test concerning correlation","f":"t = \\dfrac{r\\sqrt{n-2}}{\\sqrt{1-r^2}}, \\quad df=n-2"},{"t":"Spearman rank correlation coefficient","f":"r_S = 1 - \\dfrac{6\\sum_{i=1}^{n} d_i^2}{n(n^2-1)}"},{"t":"Contingency table test","f":"\\chi^2 = \\sum_{i=1}^{m}\\dfrac{(O_{ij}-E_{ij})^2}{E_{ij}}","n":"Standardized residual = (O_ij − E_ij)/√E_ij"}]},{"h":"Simple Linear Regression","items":[{"t":"Regression model","f":"Y = b_0 + b_1 X + \\varepsilon","n":"Y = dependent/explained variable; X = independent/explanatory variable; b0 = intercept; b1 = slope; ε = error term."},{"t":"Slope estimate","f":"\\hat{b}_1 = \\dfrac{Cov(Y,X)}{Var(X)} = \\dfrac{\\sum_{i=1}^{n}(Y_i-\\bar{Y})(X_i-\\bar{X})}{\\sum_{i=1}^{n}(X_i-\\bar{X})^2}"},{"t":"Intercept estimate","f":"\\hat{b}_0 = \\bar{Y} - \\hat{b}_1\\bar{X}"},{"t":"Correlation coefficient","f":"r = \\dfrac{Cov(X,Y)}{\\sqrt{Var(X)}\\,\\sqrt{Var(Y)}}"},{"t":"Assumptions","n":"Linear relationship between X and Y; homoscedasticity (constant variance of residuals); independence of observations; normality of the residuals."},{"t":"Sum of squares error (SSE)","f":"SSE = \\sum_{i=1}^{n}(Y_i-\\hat{Y}_i)^2","n":"Unexplained variation in Y."},{"t":"Sum of squares regression (SSR)","f":"SSR = \\sum_{i=1}^{n}(\\hat{Y}_i-\\bar{Y})^2","n":"Explained variation in Y."},{"t":"Sum of squares total (SST)","f":"SST = SSE + SSR = \\sum_{i=1}^{n}(Y_i-\\bar{Y})^2"},{"t":"Coefficient of determination","f":"R^2 = \\dfrac{SSR}{SST} = r^2 \\;\\text{(single independent variable)}"},{"t":"F-statistic","f":"F = \\dfrac{MSR}{MSE} = \\dfrac{SSR/k}{SSE/(n-[k+1])}"},{"t":"Standard error of regression","f":"s_e = \\sqrt{MSE} = \\sqrt{\\dfrac{\\sum_{i=1}^{n}(Y_i-\\hat{Y}_i)^2}{n-2}}"},{"t":"Test of slope coefficient","f":"t = \\dfrac{\\hat{b}_1-b_1}{s_{\\hat{b}_1}}, \\quad s_{\\hat{b}_1} = \\dfrac{s_e}{\\sqrt{\\sum_{i=1}^{n}(X_i-\\bar{X})^2}}"},{"t":"Test of intercept","f":"t = \\dfrac{\\hat{b}_0-b_0}{s_{\\hat{b}_0}}, \\quad s_{\\hat{b}_0} = s_e\\sqrt{\\dfrac{1}{n}+\\dfrac{\\bar{X}^2}{\\sum_{i=1}^{n}(X_i-\\bar{X})^2}}"},{"t":"Prediction error variance","f":"s_f^2 = s_e^2\\left[1 + \\dfrac{1}{n} + \\dfrac{(X-\\bar{X})^2}{(n-1)s_X^2}\\right]"},{"t":"Functional forms","n":"Common functional forms: log-lin model, lin-log model, log-log model."}]},{"h":"Big Data Techniques","items":[{"t":"Fintech & big data","n":"Big data characteristics: Volume, Velocity, Variety. Alternative data sources: individuals, business processes, sensors. Machine learning types: supervised, unsupervised, deep learning."}]},{"h":"BA II Plus Calculator Tips","items":[{"t":"Basic operations","n":"2ND: yellow secondary functions. ENTER: send value to a variable. 2ND+ENTER: toggle options. ↑/↓: navigate variables. STO + 0–9: store to memory. RCL + 0–9: recall from memory."},{"t":"Time value of money (TVM)","n":"N: number of periods. I/Y: effective rate per period (%). PV, PMT, FV as usual. CPT + a key: solve for the unknown. 2ND+BGN: toggle ordinary annuity vs. annuity due. Always clear the TVM worksheet first. For bonds, PMT and FV share a sign opposite to PV."},{"t":"Cash flow worksheet (CF, NPV, IRR)","n":"CF0: initial cash flow. C01…C0n: distinct subsequent cash flows; F01…F0n: their frequencies. Always clear the CF worksheet first. NPV: enter I, then NPV+CPT. IRR: IRR+CPT."}]}]},{"id":"econ","name":"Economics","sections":[{"h":"Firms and Market Structures","items":[{"t":"Profit maximization","f":"MR = MC"},{"t":"Economic profit","f":"\\text{Revenue} > \\text{Explicit costs} + \\text{Implicit costs}","n":"Normal profit: economic profit = 0."},{"t":"Shutdown decision","n":"TR ≥ TC: stay short-term, stay long-term. TVC < TR < TC: stay short-term, exit long-term. TR < TVC: shut down short-term, exit long-term."},{"t":"Economies of scale","n":"Each expansion stage has its own short-run ATC curve. Minimum efficient scale = low point of the long-run average total cost curve."},{"t":"Market structures","n":"Perfect competition: many firms, homogeneous products, very low barriers, no pricing power. Monopolistic competition: many firms, differentiated products, low barriers, some pricing power. Oligopoly: few firms, homogeneous, high barriers, some/considerable pricing power. Monopoly: one firm, unique product, very high barriers, considerable pricing power."},{"t":"Oligopoly models","n":"Kinked demand curve: a price increase impacts sales more than an equal price decrease. Cournot: competitors maintain output if one firm changes price. Game theory: firms adjust to maximize profit → Nash equilibrium."},{"t":"N-firm concentration ratio","n":"Sum of the market share of the N largest firms in the industry."},{"t":"Herfindahl-Hirschman Index (HHI)","f":"HHI = \\sum_{i=1}^{N} (\\text{market share}_i)^2","n":"Sum of squared market shares of the N largest firms."}]},{"h":"Understanding Business Cycles","items":[{"t":"Business cycle phases","n":"Recovery: through trough, below potential but rising, moderate inflation, low but increasing capital spending. Expansion: upswing, above-average growth, moderate/rising inflation, capacity-expansion capital spending. Slowdown: peak, decelerating, accelerating inflation, inventory building. Contraction: recession, below potential, layoffs, decelerating inflation (lagged)."},{"t":"Economic indicators","n":"Leading: stock indexes, building permits. Coincident: real income, industrial production. Lagging: unemployment rate, prime lending rate."}]},{"h":"Fiscal Policy","items":[{"t":"Fiscal policy tools","n":"Spending tools: transfer payments (redistribution), current spending (goods & services), capital spending (infrastructure). Revenue tools: direct taxes (income), indirect taxes (goods & services)."},{"t":"Fiscal multiplier","f":"\\text{Fiscal multiplier} = \\dfrac{1}{1 - MPC(1-t)}","n":"MPC = marginal propensity to consume; t = tax rate."},{"t":"Difficulties executing fiscal policy","n":"Recognition lag: government must recognize the need. Action lag: time to choose policy. Impact lag: policies do not have immediate effect."}]},{"h":"Monetary Policy","items":[{"t":"Roles of central banks","n":"Supplier of currency; banker to government & banks' bank; lender of last resort; regulator of payments system; conductor of monetary policy; supervisor of banking; holder of FX & gold reserves."},{"t":"Monetary policy tools","n":"Expansionary: open-market operations (buy bonds from banks), set policy rate below neutral, reduce reserve requirement. Contractionary: reverse."}]},{"h":"Geopolitics","items":[{"t":"Geopolitical actors & risk","n":"National governments cooperate politically. State actors deploy national security resources. Non-state actors participate but do not control resources. Geopolitical risk types: event, exogenous, thematic. Assess by likelihood, velocity (speed), and size/nature of impact."}]},{"h":"International Trade & Capital Flows","items":[{"t":"Benefits & costs of trade","n":"Benefits: gains from exchange, greater economies of scale, greater product variety, increased competition, more efficient resource allocation. Costs: income inequality, job losses."},{"t":"Trade restrictions","n":"Tariff: tax on imported goods. Quota: limit on quantity imported. Export subsidies: payments to exporters. Minimum domestic content requirement. Voluntary export restraints: self-imposed limits by foreign producers."},{"t":"Impact of a tariff/quota","n":"Price rises P*→P1; domestic production Q1→Q2; consumption Q4→Q3; imports (Q4−Q1)→(Q3−Q2). Loss of consumer surplus = A+B+C+D; national welfare loss = B+D; producer surplus gain = A; tariff revenue/quota rent = C."},{"t":"Regional trading blocs","n":"FTA: free trade among members. Customs union: FTA + common trade policy. Common market: CU + free movement of factors. Economic union: CM + common economic institutions. Monetary union: EU + single currency."}]},{"h":"Capital Flows & the FX Market","items":[{"t":"Real exchange rate","f":"\\text{Real rate}_{A/B} = \\text{Nominal rate}_{A/B} \\times \\dfrac{CPI_B}{CPI_A}","n":"A/B = units of currency A per one unit of currency B."},{"t":"Ideal currency regime","n":"(1) Credibly fixed exchange rates, (2) fully convertible currencies with free capital flows, (3) independent monetary policy. This ideal is NOT simultaneously possible."},{"t":"Exchange rate regimes","n":"Dollarization, monetary union, currency board, fixed peg, target zone, crawling peg, crawling bands, managed float, independent float."}]},{"h":"Exchange Rate Calculations","items":[{"t":"Trade balance identity","f":"X - M = (S - I) + (T - G)","n":"A trade surplus must be reflected in excess private savings or a fiscal surplus."},{"t":"Cross-rate","f":"S_{A/B} = S_{A/C} \\times S_{C/B}"},{"t":"Forward rate","f":"\\dfrac{\\text{Forward}_{A/B}}{\\text{Spot}_{A/B}} = \\dfrac{1+i_d}{1+i_f}","n":"i_d = domestic (price currency) rate, i_f = foreign (base currency) rate."}]}]},{"id":"fsa","name":"Financial Statement Analysis","sections":[{"h":"Introduction to FSA","items":[{"t":"Regulated sources of information","n":"IOSCO: international body of securities regulators. SEC: US capital markets regulator."}]},{"h":"Analyzing Income Statements","items":[{"t":"Revenue recognition","n":"Recognize revenue only when: risks of ownership transferred, amount reliably measured, customer likely to pay, transaction unlikely to be reversed. Allowance for doubtful accounts is a contra-asset estimated from historical experience."},{"t":"Expense recognition","n":"Matching principle: expenses recognized in the same period as associated revenue. Capitalizing increases assets and investing outflows; expensing reduces net income by the after-tax amount in the period incurred."},{"t":"Income statement structure","f":"\\begin{aligned}&\\text{Revenue} - \\text{COGS} = \\text{Gross profit}\\\\ &-\\text{SG\\&A} = \\text{EBITDA}\\\\ &-\\text{D\\&A} = \\text{EBIT (operating profit)}\\\\ &-\\text{Interest} = \\text{EBT}\\\\ &-\\text{Taxes} = \\text{Net income}\\end{aligned}"},{"t":"Basic EPS","f":"\\text{Basic EPS} = \\dfrac{\\text{Net income} - \\text{Preferred dividends}}{\\text{Weighted avg. shares outstanding}}"},{"t":"Diluted EPS","f":"\\text{Diluted EPS} = \\dfrac{NI - \\text{Pref. div.} + \\text{Conv. pref. div.} + \\text{Conv. debt interest}(1-t)}{\\text{Wtd avg shares} + \\text{Conv. pref.} + \\text{Conv. debt} + \\text{Options}}","n":"Diluted EPS must be ≤ basic EPS."},{"t":"Separately reported items","n":"Unusual or infrequent items (US GAAP only), discontinued operations, non-operating items."}]},{"h":"Analyzing Balance Sheets","items":[{"t":"Non-current items","n":"Non-current assets: intangible assets, goodwill, financial instruments. Non-current liabilities: long-term financial liabilities, deferred tax liabilities."}]},{"h":"Analyzing Cash Flow Statements","items":[{"t":"AP / inventory relationship","f":"\\Delta AP + \\text{Cash paid to suppliers} = \\Delta \\text{Inventory} + COGS"},{"t":"Direct vs. indirect CFO","n":"Direct: convert each accrual income-statement item to cash. Indirect: start with net income, add non-cash expenses (depreciation), subtract gains/add losses, add increases in current liabilities, subtract increases in non-cash current assets."},{"t":"Cash collected from customers","f":"\\text{Cash from customers} = \\text{Beginning AR} + \\text{Revenue} - \\text{Ending AR}"},{"t":"Cash paid to suppliers","f":"\\text{Cash to suppliers} = COGS + \\Delta\\text{Inventory} - \\Delta AP"},{"t":"IFRS vs. US GAAP cash flow classification","n":"Interest received: IFRS operating/investing, GAAP operating. Interest paid: IFRS operating/financing, GAAP operating. Dividends received: IFRS operating/investing, GAAP operating. Dividends paid: IFRS operating/financing, GAAP financing. Bank overdrafts: IFRS cash equivalents, GAAP financing."},{"t":"Free cash flow to the firm (FCFF)","f":"FCFF = NI + NCC + I(1-t) - WCI - FCI = CFO + I(1-t) - FCI","n":"Cash available to both equity owners and debt holders."},{"t":"Free cash flow to equity (FCFE)","f":"FCFE = CFO - FCI + \\text{Net borrowing}","n":"Cash available to common shareholders."}]},{"h":"Analysis of Inventories","items":[{"t":"Inventory valuation","n":"IFRS: lower of cost or net realizable value. US GAAP: lower of cost or market value. Write-down reversals allowed under IFRS but not US GAAP. LIFO allowed under US GAAP, not IFRS."},{"t":"Inventory method impact (rising prices)","n":"FIFO: higher ending inventory, lower COGS, higher net income, higher taxes, lower operating cash flow. LIFO: the reverse."}]},{"h":"Analysis of Long-Term Assets","items":[{"t":"Impairment of PP&E — IFRS","n":"Both cost and revaluation models allowed. Impairment loss = carrying amount − recoverable amount, where recoverable amount = greater of (fair value less selling costs) or (value in use). Loss recoveries allowed."},{"t":"Impairment of PP&E — US GAAP","n":"Only cost model allowed. Tested when carrying value may not be recovered; impaired if carrying value > undiscounted future cash flows; written down to fair value. Impairment loss = carrying amount − fair value. Recoveries not allowed."}]},{"h":"Long-Term Liabilities & Equity","items":[{"t":"Lease classification","n":"Finance lease if any: ownership transfers, bargain purchase option, term covers most of useful life, PV of payments ≈ fair value, or asset is specialized to the lessee."},{"t":"Lessee & lessor accounting","n":"Lessee finance lease: separate depreciation & interest. Operating lease (US GAAP): single straight-line expense. IFRS treats all lessee leases like finance leases. Lessor keeps operating-lease assets on B/S (records rent as revenue); removes finance-lease assets and books a lease receivable."},{"t":"Defined benefit pension components","n":"IFRS: current service cost (I/S), net interest (I/S), remeasurement (OCI). US GAAP: current service cost, interest expense, expected return on plan assets (all I/S); past service cost (OCI, amortized); actuarial gains/losses (I/S, amortized in OCI)."},{"t":"Share-based compensation","n":"Stock grants (outright or restricted), stock options, stock appreciation rights (SARs), phantom shares."}]},{"h":"Analysis of Income Taxes","items":[{"t":"Temporary differences (DTL/DTA)","n":"DTL: created when taxes payable < income tax expense. DTA: created when taxes payable > income tax expense. Asset carrying > tax base → DTL; asset < tax base → DTA. Liability carrying > tax base → DTA; liability < tax base → DTL."},{"t":"Tax rate changes & valuation allowance","n":"If tax rate rises, DTA & DTL rise; if it falls, they fall. Valuation allowance: contra-account when future profits are unlikely to be sufficient to use DTAs."},{"t":"Corporate tax rates","n":"Statutory rate: domestic corporate income tax rate. Effective tax rate: reported income tax expense ÷ EBT. Cash tax rate: actual income tax paid ÷ EBT."}]},{"h":"Financial Reporting Quality","items":[{"t":"Spectrum of reporting quality","n":"(1) GAAP, decision-useful, sustainable, adequate returns; (2) GAAP, decision-useful, but sustainability questionable; (3) biased accounting choices; (4) within GAAP but 'earnings management'; (5) departures from GAAP."},{"t":"Straight-line depreciation","f":"\\text{Depreciation} = \\dfrac{\\text{Cost} - \\text{Salvage value}}{\\text{Depreciable life}}"},{"t":"Double-declining balance (DDB)","f":"\\text{Depreciation}_t = \\dfrac{\\text{Book value}_t}{\\text{Depreciable life}} \\times 2"},{"t":"Units-of-production depreciation","f":"\\text{Depreciation}_t = \\dfrac{\\text{Cost} - \\text{Salvage}}{\\text{Total output}} \\times \\text{Output units}_t"}]},{"h":"Financial Analysis Techniques","items":[{"t":"Common-size analysis","n":"Vertical: income items as % of revenue, balance-sheet items as % of total assets, cash-flow items as % of total inflows/outflows. Horizontal (trend): each item relative to its base-year value."}]},{"h":"Activity Ratios","items":[{"t":"Total asset turnover","f":"\\dfrac{\\text{Revenue}}{\\text{Average total assets}}"},{"t":"Fixed asset turnover","f":"\\dfrac{\\text{Revenue}}{\\text{Average net fixed assets}}"},{"t":"Working capital turnover","f":"\\dfrac{\\text{Revenue}}{\\text{Average working capital}}"},{"t":"Inventory turnover","f":"\\dfrac{\\text{Cost of goods sold}}{\\text{Average inventory}}"},{"t":"Receivables turnover","f":"\\dfrac{\\text{Annual sales}}{\\text{Average receivables}}"},{"t":"Payables turnover","f":"\\dfrac{\\text{Purchases}}{\\text{Average trade payables}}"},{"t":"Days ratios","f":"\\text{DOH}=\\dfrac{365}{\\text{Inv. turnover}},\\;\\; \\text{DSO}=\\dfrac{365}{\\text{Rec. turnover}},\\;\\; \\text{Days payables}=\\dfrac{365}{\\text{Pay. turnover}}"}]},{"h":"Liquidity Ratios","items":[{"t":"Current / quick / cash ratio","f":"\\text{Current}=\\dfrac{CA}{CL},\\;\\; \\text{Quick}=\\dfrac{\\text{Cash}+\\text{Mkt sec.}+\\text{Rec.}}{CL},\\;\\; \\text{Cash}=\\dfrac{\\text{Cash}+\\text{Mkt sec.}}{CL}"},{"t":"Defensive interval","f":"\\dfrac{\\text{Cash}+\\text{Mkt sec.}+\\text{Receivables}}{\\text{Average daily expenditures}}"},{"t":"Cash conversion cycle","f":"\\text{CCC} = DSO + DOH - \\text{Days payables}"}]},{"h":"Solvency Ratios","items":[{"t":"Debt ratios","f":"\\dfrac{\\text{Total debt}}{\\text{Total equity}},\\;\\; \\dfrac{\\text{Total debt}}{\\text{Debt}+\\text{Equity}},\\;\\; \\dfrac{\\text{Total debt}}{\\text{Total assets}},\\;\\; \\dfrac{\\text{Total debt}}{\\text{EBITDA}}"},{"t":"Financial leverage","f":"\\dfrac{\\text{Average total assets}}{\\text{Average total equity}}"},{"t":"Interest & fixed-charge coverage","f":"\\text{Int. coverage}=\\dfrac{EBIT}{\\text{Interest}},\\;\\; \\text{Fixed charge}=\\dfrac{EBIT+\\text{Lease pmts}}{\\text{Interest}+\\text{Lease pmts}}"}]},{"h":"Profitability Ratios","items":[{"t":"Margins","f":"\\text{Net}=\\dfrac{NI}{Rev},\\; \\text{Gross}=\\dfrac{\\text{Gross profit}}{Rev},\\; \\text{Operating}=\\dfrac{EBIT}{Rev},\\; \\text{Pretax}=\\dfrac{EBT}{Rev}"},{"t":"Return ratios","f":"ROA=\\dfrac{NI}{\\text{Avg assets}},\\;\\; ROIC=\\dfrac{EBIT(1-t)}{\\text{ST\\&LT debt}+\\text{equity}},\\;\\; ROE=\\dfrac{NI}{\\text{Avg equity}}"}]},{"h":"DuPont Analysis","items":[{"t":"3-way DuPont","f":"ROE = \\underbrace{\\dfrac{NI}{Rev}}_{\\text{Net margin}} \\times \\underbrace{\\dfrac{Rev}{\\text{Assets}}}_{\\text{Asset turnover}} \\times \\underbrace{\\dfrac{\\text{Assets}}{\\text{Equity}}}_{\\text{Leverage}}"},{"t":"5-way DuPont","f":"ROE = \\dfrac{NI}{EBT}\\times\\dfrac{EBT}{EBIT}\\times\\dfrac{EBIT}{Rev}\\times\\dfrac{Rev}{\\text{Assets}}\\times\\dfrac{\\text{Assets}}{\\text{Equity}}","n":"= Tax burden × Interest burden × EBIT margin × Asset turnover × Financial leverage."}]},{"h":"Financial Statement Modeling","items":[{"t":"Behavioral biases & Porter's Five Forces","n":"Analyst biases: overconfidence, illusion of control, conservatism, representativeness, confirmation. Porter's Five Forces: threat of substitutes, rivalry intensity, supplier power, buyer power, threat of new entrants."}]}]},{"id":"ci","name":"Corporate Issuers","sections":[{"h":"Organizational Forms & Ownership","items":[{"t":"Business structures","n":"Sole proprietorship: owner operates & retains liability. General partnership: liability shared by all partners. Limited partnership: GP has unlimited liability, LPs limited. LLP: all partners have limited liability. Limited company: legal identity separate from owners; financed by equity and debt."},{"t":"Private vs. public issuers","n":"Private companies raise capital via private placement memorandum (PPM). Go public via IPO, direct listing (DL), acquisition, or leveraged buyout (LBO)."}]},{"h":"Investors & Other Stakeholders","items":[{"t":"Equity vs. debt characteristics","n":"Upside potential: equity unlimited, debt limited to payments. Maximum loss: equity up to investment value, debt limited. Investment risk: equity higher, debt lower. Interest: equity maximizes company value, debt seeks timely repayment."}]},{"h":"Corporate Governance","items":[{"t":"Ownership & conflicts","n":"Dispersed ownership: controlled by many minority shareholders. Concentrated ownership: controlled by a single shareholder. Multiple share-class structures create disproportionate voting power. Conflicts: shareholder–manager (agency), shareholder–creditor."},{"t":"Governance mechanisms","n":"Shareholder: transparency, cumulative voting, activism, proxy contests/tender offers. Board: audit, governance, remuneration, nomination, risk, investment committees. Risks of poor governance: weak controls, ineffective decisions, inadequate scrutiny — leading to higher default and borrowing costs."}]},{"h":"Working Capital & Liquidity","items":[{"t":"Cash conversion cycle","f":"\\text{CCC} = DOH + DSO - DPO"},{"t":"EAR of supplier (trade credit) financing","f":"\\text{EAR} = \\left(1 + \\dfrac{d}{1-d}\\right)^{\\frac{365}{\\text{Payment period} - \\text{Discount period}}} - 1","n":"d = the discount percentage."},{"t":"Working capital","f":"\\text{Working capital} = \\text{Current assets} - \\text{Current liabilities}"},{"t":"Cash flow from operations (CFO)","f":"CFO = \\text{Cash from customers} + \\text{Interest \\& dividends} - \\text{Paid to employees} - \\text{Paid to suppliers} - \\text{Taxes} - \\text{Interest paid}"},{"t":"Free cash flow (to equity)","f":"FCFE = CFO - \\text{Investments in long-term assets}"},{"t":"Sources of liquidity","n":"Primary: free cash flow, ready-cash balances, short-term credit lines, centralized cash management. Secondary: negotiating debt contracts, liquidating assets, filing for bankruptcy. Drag: delayed inflows (uncollected receivables). Pull: accelerated outflows (early payables)."},{"t":"Current ratio","f":"\\text{Current ratio} = \\dfrac{\\text{Current assets}}{\\text{Current liabilities}}"},{"t":"Quick ratio","f":"\\text{Quick ratio} = \\dfrac{\\text{Cash} + \\text{Marketable securities} + \\text{Receivables}}{\\text{Current liabilities}}"},{"t":"Cash ratio","f":"\\text{Cash ratio} = \\dfrac{\\text{Cash} + \\text{Marketable securities}}{\\text{Current liabilities}}"},{"t":"Working capital approaches","n":"Conservative: low rollover risk, greater cash-flow certainty, but higher financing costs and dilution. Aggressive: lower financing costs (upward-sloping yield curve), greater flexibility, but refinancing/rollover risk."}]},{"h":"Capital Investments & Allocation","items":[{"t":"Types of capital investments","n":"Business maintenance: going-concern & regulatory/compliance projects. Business growth: expansion projects, pet/high-risk projects."},{"t":"Net present value (NPV)","f":"NPV = \\sum_{t=1}^{n}\\dfrac{CF_t}{(1+r)^t} - \\text{Outlay}","n":"Accept a project if NPV > 0."},{"t":"Internal rate of return (IRR)","f":"\\sum_{t=1}^{n}\\dfrac{CF_t}{(1+IRR)^t} - \\text{Outlay} = 0","n":"IRR is the rate at which NPV = 0. Accept if IRR > required return."},{"t":"Return on invested capital (ROIC)","f":"ROIC = \\dfrac{\\text{After-tax net profit}}{\\text{Avg. BV of invested capital}} = \\dfrac{(1-\\text{Tax rate})\\times\\text{Operating profit}}{\\text{Avg.(LT liabilities}+\\text{equity})}"},{"t":"Capital allocation pitfalls","n":"Internal forecasting errors, ignoring internal financing costs, inconsistent inflation treatment, inertia, basing decisions on earnings metrics, pet projects, failing to consider alternatives."},{"t":"Real options","n":"Timing: delay the investment. Sizing: expand, grow, or abandon. Flexibility: alter operations (prices/inputs). Fundamental: decisions based on future events. Analyze via DCF, DCF + PV of options, option-pricing models, or decision trees."}]},{"h":"Capital Structure","items":[{"t":"Weighted average cost of capital (WACC)","f":"WACC = w_d r_d(1-t) + w_p r_p + w_e r_e","n":"w = capital-structure weights; r = component costs; t = tax rate."},{"t":"Determinants of cost of debt & equity","n":"Issuer-specific: sales risk, profitability risk (operating leverage), financial leverage & interest coverage, asset type (tangible, fungible, liquid)."},{"t":"MM Propositions","n":"MM I: capital structure does not affect firm value under perfect markets (homogeneous expectations, no frictions/taxes/distress costs, no agency costs, risk-free borrowing, independent decisions). MM II: cost of equity rises with the D/E ratio."},{"t":"MM without taxes","f":"V_L = V_U \\qquad r_e = r_0 + (r_0 - r_d)\\dfrac{D}{E}"},{"t":"MM with taxes","f":"V_L = V_U + tD \\qquad r_e = r_0 + (r_0 - r_d)(1-t)\\dfrac{D}{E}","n":"r_0 = cost of capital for an all-equity firm."},{"t":"Static trade-off theory","f":"V_L = V_U + tD - PV(\\text{costs of financial distress})","n":"Balances the tax shield of debt against financial-distress costs to find the optimal capital structure."},{"t":"Pecking-order theory","n":"Due to asymmetric information, managers prefer sources revealing least information: (1) internally generated earnings, (2) new debt, (3) new equity (least attractive)."}]},{"h":"Business Models","items":[{"t":"Value chain, supply chain, unit economics","n":"Value chain: systems/functions within the firm that create value for customers. Supply chain: steps to prepare a product for sale. Unit economics: quantitative analysis of revenues and costs on a per-unit basis."},{"t":"Pricing & revenue models","n":"Price discrimination; tiered, dynamic, value-based, auction pricing. Multiple products: bundling, razors-and-blades, add-on. Rapid growth: penetration, freemium, hidden revenue. Ownership alternatives: subscription, leasing, licensing, franchising, fractionalization."}]}]},{"id":"equity","name":"Equity Investments","sections":[{"h":"Market Organization & Structure","items":[{"t":"Functions of the financial system","n":"Saving, borrowing, raising equity capital, managing risks, exchanging assets, information-motivated trading."},{"t":"Securities markets","n":"Spot vs forward: spot settles within ~3 days. Primary vs secondary: primary is directly with the issuer; secondary trades on exchanges. Capital vs money markets: money market = maturities < 1 year; capital market = longer-dated."},{"t":"Positions","n":"Long positions benefit from price appreciation; short positions benefit from price depreciation."},{"t":"Leverage ratio","f":"\\text{Leverage ratio} = \\dfrac{\\text{Position}}{\\text{Equity}} \\qquad \\text{Max initial leverage} = \\dfrac{1}{\\text{Initial margin}}","n":"Margin call triggered when equity falls below the maintenance margin."},{"t":"Order execution instructions","n":"Market: fill immediately. Limit: buy below max / sell above min. All-or-nothing: cancel if not fully filled. Hidden: visible only to brokers/exchanges. Iceberg: only a fraction visible. Day orders cancel at end of day; good-till-cancelled persists; stop-loss sells below a level."},{"t":"Primary market transactions","n":"IPO, private placement, shelf registration (issue held back for later), DRIPs (reinvest dividends into new shares), rights offerings (buy new shares below market, dilutes existing shares)."},{"t":"Market structure & pricing rules","n":"Quote-driven: trade with dealers. Order-driven: order-matching rules. Brokered: arranged by brokers. Call markets: periodic single-price auctions. Continuous markets: trade anytime open. Uniform pricing (call markets); discriminatory pricing (continuous); derivative pricing (crossing networks at midpoint)."}]},{"h":"Security Market Indexes","items":[{"t":"Price return (single period)","f":"PR_i = \\dfrac{P_{i1}-P_{i0}}{P_{i0}} \\qquad PR_I = \\sum_{i=1}^{N} w_i PR_i"},{"t":"Total return (single period)","f":"TR_i = \\dfrac{P_{i1}-P_{i0}+Inc_i}{P_{i0}} \\qquad TR_I = \\sum_{i=1}^{N} w_i TR_i"},{"t":"Price return index (multi-period)","f":"V_{PRIT} = V_{PRI0}(1+PR_{I1})(1+PR_{I2})\\cdots(1+PR_{IT})"},{"t":"Total return index (multi-period)","f":"V_{TRIT} = V_{TRI0}(1+TR_{I1})(1+TR_{I2})\\cdots(1+TR_{IT})"},{"t":"Price-weighted index weight","f":"w_i^P = \\dfrac{P_i}{\\sum_{i=1}^{N} P_i}","n":"Like buying one share of each stock. Simple, but arbitrary weights; splits require divisor adjustment."},{"t":"Equally weighted index weight","f":"w_i^E = \\dfrac{1}{N}","n":"Like investing the same amount in each stock. Simple, but underrepresents large firms and needs frequent rebalancing."},{"t":"Capitalization-weighted index weight","f":"w_i^M = \\dfrac{Q_i P_i}{\\sum_{i=1}^{N} Q_i P_i}","n":"Holds stocks in proportion to market value; float adjustment reflects tradable shares; can be dragged by large-cap (possibly overvalued) firms."},{"t":"Types of equity indexes","n":"Broad market (one market), multi-market (multiple countries), sector (selection vs. allocation), style (large/small cap, value/growth). Fundamentally weighted indexes have a value tilt."}]},{"h":"Market Efficiency","items":[{"t":"Forms of EMH","n":"Weak: prices reflect past market data → technical analysis cannot earn abnormal profit. Semi-strong: reflect all public info → need comparative advantage for fundamental analysis. Strong: reflect all public and private info."},{"t":"Behavioral biases","n":"Loss aversion, information cascades, representativeness, mental accounting, conservatism, narrow framing. Market anomalies = price changes not attributable to known information."}]},{"h":"Overview of Equity Securities","items":[{"t":"Voting methods","n":"Statutory: one vote per share. Cumulative: votes can be bundled onto one candidate — advantages small shareholders."},{"t":"Preference shares","n":"Cumulative: missed dividends accrue. Non-cumulative: missed dividends don't accrue (but no common dividends until preferred paid). Participating: extra dividend if profitable or on liquidation. Non-participating: only face value + dividends."},{"t":"Private equity securities","n":"Venture capital (VC): start-up/early-stage/mezzanine with IPO exit. Leveraged buyout (LBO): debt-financed take-private of undervalued firms. PIPE: quick capital raise, investors negotiate discounts."},{"t":"Depository receipts (DRs)","n":"Sponsored: issued directly by the foreign company (voting rights). Unsponsored: depository bank buys shares & keeps voting. Global DRs: issued outside home country (usually USD). American DRs: USD-denominated, trade on US exchanges. Global registered shares: actual ownership, multiple exchanges/currencies."}]},{"h":"Company Analysis","items":[{"t":"Operating income & leverage","f":"\\text{Operating income} = [Q\\times(P-VC)] - FC","n":"DOL = %ΔOperating income / %ΔSales. DFL = %ΔNet income / %ΔOperating income. DTL = DOL × DFL."},{"t":"Industry & competitive analysis","n":"Steps: define industry, survey, structure, external influences, competitive analysis. External influences (PESTLE): political, economic, social, technological, legal, environmental. Forecast revenue top-down (GDP/market share) or bottom-up (volume × price, segments)."}]},{"h":"Equity Valuation","items":[{"t":"Dividend discount model (DDM)","f":"V_0 = \\sum_{t=1}^{n}\\dfrac{D_t}{(1+r)^t} + \\dfrac{P_n}{(1+r)^n}"},{"t":"Preferred stock (constant dividend)","f":"V_0 = \\dfrac{D_0}{r}"},{"t":"Gordon (constant) growth model","f":"V_0 = \\dfrac{D_0(1+g)}{r-g} = \\dfrac{D_1}{r-g}","n":"g = Retention rate × ROE = (1 − payout ratio) × ROE."},{"t":"Multistage DDM terminal value","f":"P_n = \\dfrac{D_{n+1}}{r-g_L}, \\quad D_{n+1} = D_n(1+g_L)"},{"t":"Price multiples","f":"\\dfrac{P}{E},\\;\\; \\dfrac{P}{B}=\\dfrac{\\text{Price}}{\\text{Book value/share}},\\;\\; \\dfrac{P}{CF}=\\dfrac{\\text{Price}}{\\text{CF/share}},\\;\\; \\dfrac{P}{S}=\\dfrac{\\text{Price}}{\\text{Sales/share}}"},{"t":"Enterprise value (EV)","f":"EV = MV_{\\text{equity}} + MV_{\\text{preferred}} + MV_{\\text{debt}} - (\\text{Cash} + \\text{ST investments})"},{"t":"Asset-based valuation","n":"Useful for firms with natural resources or a large share of current assets/liabilities; not useful for firms with large PP&E/intangibles."}]}]},{"id":"fi","name":"Fixed Income","sections":[{"h":"Fixed-Income Features & Cash Flows","items":[{"t":"Cash flow structures","n":"Bullet: full principal at maturity. Fully amortized: equal payments (interest + principal). Partially amortized: some amortization + balloon. Sinking fund: retire a % each year. FRN: reference rate + spread. Step-up: scheduled coupon increases. Sustainability-linked/credit-linked: coupon adjusts to targets/ratings. PIK: coupons paid in more bonds. Index-linked: coupon tied to an index. Deferred/split coupon: no early coupons, high later."},{"t":"Callable & putable bonds","f":"V_{\\text{callable}} = V_{\\text{non-callable}} - V_{\\text{call}} \\qquad V_{\\text{putable}} = V_{\\text{non-putable}} + V_{\\text{put}}"},{"t":"Convertible bonds","n":"Conversion price: share price at which the bond converts. Conversion ratio: shares per bond. Conversion value = current share price × conversion ratio. Conversion premium = convertible price − conversion value. CoCos: auto-convert to equity if a condition (e.g., capital ratio) is breached; mostly issued by financial institutions."},{"t":"Fixed-income markets","n":"Primary market: issuers first sell bonds to raise capital. Secondary market: bonds traded among investors, mostly OTC rather than on organized exchanges."}]},{"h":"Fixed-Income Markets","items":[{"t":"External financing sources","n":"Loan financing: uncommitted/committed lines of credit, revolving credit, secured (asset-based) loans, factoring. Security-based: commercial paper (CP) with a backup line of credit."},{"t":"Repurchase (repo) price","f":"\\text{Repo price} = \\text{Purchase price}\\times\\left[1 + \\text{Repo rate}\\times\\dfrac{\\text{Days}}{360}\\right]"},{"t":"Repo margin & haircut","f":"\\text{Initial margin} = \\dfrac{\\text{Security price}}{\\text{Purchase price}} \\qquad \\text{Haircut} = \\dfrac{\\text{Security price}-\\text{Purchase price}}{\\text{Security price}}"},{"t":"Sovereign & non-sovereign debt","n":"Sovereign: national governments, ~zero default risk; bills < 1yr, bonds > 1yr; on-the-run issues are most recent and most liquid. Non-sovereign: municipal (sub-national), quasi-government (agencies), supranational (IMF, World Bank)."}]},{"h":"Fixed-Income Valuation","items":[{"t":"Bond pricing with market discount rate","f":"PV = \\dfrac{PMT}{(1+r)^1} + \\dfrac{PMT}{(1+r)^2} + \\cdots + \\dfrac{PMT+FV}{(1+r)^N}","n":"Par: coupon = r, PV = FV. Discount: coupon < r, PV < FV. Premium: coupon > r, PV > FV."},{"t":"Flat price, accrued interest, full price","f":"PV^{Full} = PV^{Flat} + AI = PV(1+r)^{t/T} \\qquad AI = \\dfrac{t}{T}\\times PMT"},{"t":"Price–yield relationships","n":"Inverse effect: price moves opposite to yield. Convexity: falling yield raises price more than an equal rise lowers it. Coupon effect: bigger impact on lower-coupon bonds. Maturity effect: bigger impact on longer-term bonds. Constant-yield trajectory: discount/premium bonds are pulled to par."},{"t":"Current & simple yield","f":"\\text{Current yield} = \\dfrac{\\text{Annual coupon}}{\\text{Flat price}} \\qquad \\text{Simple yield} = \\dfrac{\\text{Annual coupon}+\\text{Amortized gain/loss}}{\\text{Flat price}}","n":"Yield-to-call (YTC) = IRR assuming the bond is called. Yield-to-worst = min[YTC, YTM]."},{"t":"Yield spread measures","n":"Benchmark spread = YTM − benchmark yield. G-spread = YTM − government yield. I-spread = YTM − swap rate. Z-spread: constant spread over spot curve (solved by trial-and-error). OAS = Z-spread − option value (bps)."},{"t":"FRN quoted vs. discount margin","n":"Quoted margin (QM): spread paid by the FRN. Discount margin (DM): spread required by the market. If QM > DM, the FRN trades above par."},{"t":"Money market yields (DR & AOR)","f":"PV = FV\\left(1 - \\dfrac{\\text{Days}}{\\text{Year}}\\times DR\\right) \\qquad PV = \\dfrac{FV}{1 + \\frac{\\text{Days}}{\\text{Year}}\\times AOR}"},{"t":"Bond pricing with spot rates","f":"PV = \\dfrac{PMT}{(1+z_1)^1} + \\dfrac{PMT}{(1+z_2)^2} + \\cdots + \\dfrac{PMT+FV}{(1+z_N)^N}"},{"t":"Forward rates from spot rates","f":"(1+z_A)^A(1+IFR_{A,B-A})^{B-A} = (1+z_B)^B"},{"t":"Spot, par & forward curves","n":"Upward sloping: par curve below spot, forward curve above spot. Flat: both equal to spot. Inverted: par above spot, forward below spot."}]},{"h":"Fixed-Income Risk & Returns","items":[{"t":"Macaulay duration","f":"D_{Mac} = \\left\\{\\dfrac{1+r}{r} - \\dfrac{1+r+N(c-r)}{c[(1+r)^N-1]+r}\\right\\} - \\dfrac{t}{T}","n":"r = YTM, c = coupon rate, N = periods to maturity, t/T = fraction of coupon period elapsed."},{"t":"Duration gap","f":"\\text{Duration gap} = D_{Mac} - \\text{Investment horizon}","n":"Positive → price risk > reinvestment risk. Negative → reinvestment risk > price risk."},{"t":"Modified duration","f":"\\text{ModDur} = \\dfrac{D_{Mac}}{1+r} \\qquad \\%\\Delta PV^{Full} \\approx -\\text{AnnModDur}\\times\\Delta\\text{Yield}"},{"t":"Approximate modified duration","f":"\\text{ApproxModDur} = \\dfrac{PV_- - PV_+}{2\\times\\Delta\\text{Yield}\\times PV_0}"},{"t":"Money duration & PVBP","f":"\\text{MoneyDur} = \\text{AnnModDur}\\times PV^{Full} \\qquad \\text{PVBP} = \\dfrac{PV_- - PV_+}{2}","n":"Basis point value (BPV) = MoneyDur × 0.0001."},{"t":"Convexity adjustment","f":"\\%\\Delta PV^{Full} \\approx -\\text{ModDur}\\times\\Delta YTM + \\tfrac{1}{2}\\times\\text{Conv}\\times(\\Delta YTM)^2"},{"t":"Approximate convexity","f":"\\text{ApproxCon} = \\dfrac{PV_- + PV_+ - 2PV_0}{(\\Delta\\text{Yield})^2\\times PV_0}"},{"t":"Effective duration & convexity","f":"\\text{EffDur} = \\dfrac{PV_- - PV_+}{2\\times\\Delta\\text{Curve}\\times PV_0} \\qquad \\text{EffCon} = \\dfrac{PV_- + PV_+ - 2PV_0}{(\\Delta\\text{Curve})^2\\times PV_0}","n":"Curve-based measures — used for bonds with embedded options."}]},{"h":"Credit Risk & Analysis","items":[{"t":"C's of credit analysis","n":"Bottom-up: Capacity, Capital, Collateral, Covenants, Character. Top-down: Conditions, Country, Currency."},{"t":"Expected loss","f":"E[\\text{Loss}] = Pr(\\text{Default})\\times\\text{Loss severity}","n":"Loss severity = 1 − Recovery rate. Investment grade: Baa3/BBB− and above. Non-investment grade: Ba1/BB+ and below."},{"t":"Seniority ranking","n":"First lien (senior secured) → second lien (secured) → senior unsecured → senior subordinated → subordinated → junior subordinated. Pari passu: creditors of the same rank share equal claim priority regardless of maturity."}]},{"h":"Securitization","items":[{"t":"Parties to a securitization","n":"Seller/depositor originates the loans. Issuer (SPV, bankruptcy-remote) creates the ABS. Servicer collects payments on the underlying loans. Covered bonds: dual recourse to issuer and cover pool."},{"t":"MBS structures","n":"Agency RMBS: government-agency issued, conforming loans. Non-agency RMBS: private, may be non-conforming. Pass-through rate = MBS coupon. CMOs use tranches (sequential-pay, Z, PO, IO, floating, residual, PAC). Prepayment risk: contraction (faster) vs. extension (slower)."},{"t":"CMBS — debt service coverage","f":"DSC = \\dfrac{\\text{Net operating income (NOI)}}{\\text{Debt service}}","n":"NOI = (Rental income − cash operating expense) − replacement reserves. Debt service = annual interest + annual principal repayment."}]}]},{"id":"deriv","name":"Derivatives","sections":[{"h":"Derivative Features","items":[{"t":"Derivative underlyings","n":"Equities, fixed-income/interest rates, currencies, commodities, credit, and other (weather, crypto, longevity risk)."},{"t":"OTC vs. exchange-traded (ETD)","n":"OTC: lower liquidity, higher trading costs, less transparency, lower standardization, higher customization, higher counterparty credit risk. ETD: the reverse."},{"t":"Forward commitments vs. contingent claims","n":"Forward commitments (obligation to trade): forwards, futures, swaps. Contingent claims (may or may not trade): options, credit derivatives."}]},{"h":"Derivative Benefits & Risks","items":[{"t":"Benefits and risks","n":"Benefits: risk allocation/transfer/management, information discovery, operational advantages, market efficiency. Risks: speculation, lack of transparency, basis risk, liquidity risk, counterparty credit risk, systemic risk. Issuer hedges: cash-flow, fair-value, net-investment."}]},{"h":"Arbitrage & Cost of Carry","items":[{"t":"No-arbitrage forward price (with carry)","f":"F_0(T) = [S_0 + PV_0(CI) - PV_0(CB)](1+r)^T","n":"CI = carry income/benefits, CB = carry costs. Continuous: F_0(T) = S_0 e^{(r_c + CB − CI)T}."},{"t":"No-arbitrage currency forward price","f":"F_{f/d,0}(T) = S_{f/d,0}\\, e^{(r_f - r_d)T}"}]},{"h":"Pricing & Valuation of Forwards","items":[{"t":"Forward price & value","f":"F_0(T) = S_0(1+r)^T \\qquad V_t(T) = S_t - \\dfrac{F_0(T)}{(1+r)^{T-t}}","n":"At maturity: long value = S_T − F_0(T); short value = −(S_T − F_0(T))."},{"t":"Implied forward rate","f":"IFR_{A,B-A} = \\left[\\dfrac{(1+z_B)^B}{(1+z_A)^A}\\right]^{1/(B-A)} - 1"},{"t":"FRA net payment","f":"\\text{Payment to FRA buyer} = (MRR - \\text{Fixed IFR})\\times\\text{Notional}\\times\\text{Period}"}]},{"h":"Pricing & Valuation of Futures","items":[{"t":"Futures price on rates","f":"f_{A,B-A} = 100 - (100\\times MRR_{A,B-A})","n":"Futures BPV = Notional × 0.0001 × Period."},{"t":"Forward vs. futures price","n":"Correlation of futures prices with interest rates: none → futures = forward; positive → futures > forward; negative → futures < forward."}]},{"h":"Pricing & Valuation of Swaps","items":[{"t":"Swap periodic settlement","f":"\\text{Settlement value} = (MRR - \\text{Swap rate})\\times\\text{Notional}\\times\\text{Period}"}]},{"h":"Pricing & Valuation of Options","items":[{"t":"Option moneyness","n":"Call ITM: S0 > X; ATM: S0 = X; OTM: S0 < X. Put ITM: S0 < X; ATM: S0 = X; OTM: S0 > X."},{"t":"Option values at expiration","f":"c_T = \\max[0, S_T - X] \\qquad p_T = \\max[0, X - S_T]"},{"t":"Option value before expiration","f":"c_t = \\max\\!\\left[0, S_t - \\dfrac{X}{(1+r)^{T-t}}\\right] + \\text{Time value}","n":"p_t = max[0, X/(1+r)^{T−t} − S_t] + Time value."},{"t":"Option arbitrage bounds","f":"\\max\\!\\left[0, S_0 - \\dfrac{X}{(1+r)^T}\\right] \\le c_0 \\le S_0","n":"Put: max[0, X/(1+r)^T − S0] ≤ p0 ≤ X."},{"t":"Factors impacting option values","n":"An increase in: underlying → call ↑, put ↓. Exercise price → call ↓, put ↑. Time to expiration → call ↑, put ↑ (except some deep-ITM puts). Risk-free rate → call ↑, put ↓. Volatility → both ↑. Payments on underlying → call ↓, put ↑."}]},{"h":"Put-Call Parity","items":[{"t":"Put-call parity","f":"c_0 + \\dfrac{X}{(1+r)^T} = S_0 + p_0","n":"Fiduciary call = protective put."},{"t":"Put-call-forward parity","f":"c_0 + \\dfrac{X}{(1+r)^T} = \\dfrac{F_0(T)}{(1+r)^T} + p_0"},{"t":"Firm value application","f":"V_0 + p_0 = c_0 + PV(D)"}]},{"h":"One-Period Binomial Model","items":[{"t":"Replication & hedge ratio","f":"V_0 = hS_0 - c_0 \\qquad h = \\dfrac{c_1^+ - c_1^-}{S_1^+ - S_1^-}"},{"t":"Risk-neutral valuation","f":"\\pi = \\dfrac{1+r-d}{u-d} \\qquad c_0 = \\dfrac{\\pi c_1^+ + (1-\\pi)c_1^-}{1+r}"}]}]},{"id":"alts","name":"Alternative Investments","sections":[{"h":"AI Features, Methods & Structures","items":[{"t":"Features & categories","n":"Narrow manager specialization, low correlation with traditional assets, large capital outlays, long horizons, illiquidity, incentive-based compensation, performance-appraisal challenges. Methods: fund investing (indirect), co-investing (hybrid), direct investing (no intermediary)."}]},{"h":"AI Performance & Returns","items":[{"t":"Hurdle rate compensation","n":"Soft hurdle: if r ≥ r_h, fee = p × r on the entire return. Hard hurdle: fee = max[0, p(r − r_h)] on excess only. Catch-up clause lets the GP catch up to full fee. High-water mark: highest value used to compute fees. Clawback: LPs recover fees if gains reverse."},{"t":"Multiple of invested capital (MOIC)","f":"\\text{MOIC} = \\dfrac{\\text{Realized value} + \\text{Unrealized value of investment}}{\\text{Total amount invested}}"},{"t":"Withdrawal restrictions","n":"Redemption fees, notice periods, lock-up periods, liquidity gates."}]},{"h":"Private Capital: Equity & Debt","items":[{"t":"Private equity strategies","n":"LBO: management buyout (existing team involved) vs. management buy-in (team replaced). Venture capital: formative-stage (angel/seed/early), later-stage (post-commercialization), mezzanine (pre-IPO). Exits: trade sale, IPO/SPAC, recapitalization, secondary sale, liquidation."},{"t":"Private debt types","n":"Venture debt (complements equity for start-ups), direct lending (senior secured loans), mezzanine debt (subordinated to senior but senior to equity), distressed debt (mature firms in financial distress)."}]},{"h":"Real Estate & Infrastructure","items":[{"t":"Real estate investment structures","n":"Private debt: mortgages, construction lending. Private equity: direct ownership, RE funds, private REITs. Public debt: MBS, CMOs, mortgage REITs. Public equity: RE corporations, REITs."},{"t":"Fund structures & benefits","n":"Open-end (infinite-life): core, core-plus. Closed-end (finite-life): value-add, opportunistic. Benefits: stable income, price appreciation, inflation hedge, diversification, tax benefits. Infrastructure: greenfield/brownfield, economic/social, direct/indirect (MLP, ETF)."}]},{"h":"Natural Resources","items":[{"t":"Commodity futures price (cost of carry)","f":"F_0(T) = S_0 e^{(r + c - i)T}","n":"c = storage cost, i = convenience yield. Contango: upward curve, low convenience yield. Backwardation: downward curve, high convenience yield."}]},{"h":"Hedge Funds","items":[{"t":"Strategies & features","n":"Strategies: equity hedge (long/short equity), event-driven (mergers etc.), relative value (pricing discrepancies), opportunistic (top-down macro). Features: few regulatory restrictions, large universe, derivatives & shorting, leverage, concentrated positions, liquidity limits, high fees."}]},{"h":"Digital Assets","items":[{"t":"Distributed ledger & tokens","n":"Tokenization represents ownership rights to physical assets on a distributed ledger. Token types: NFTs, security tokens, utility tokens, governance tokens. Investment forms — direct: centralized/decentralized exchanges; indirect: coin trusts, futures, ETFs, crypto stocks, hedge funds."}]}]},{"id":"pm","name":"Portfolio Management","sections":[{"h":"Portfolio Risk & Return I","items":[{"t":"Risk aversion","n":"Risk-averse: requires a premium to take more risk. Risk-neutral: cares only about expected return. Risk-seeking: pays a premium to take more risk."},{"t":"Utility function","f":"U = E(r) - \\tfrac{1}{2}A\\sigma^2","n":"A = degree of risk aversion: A > 0 risk-averse, A = 0 risk-neutral, A < 0 risk-seeking."},{"t":"Minimum-variance portfolios","n":"Markowitz efficient frontier lies above the global minimum-variance portfolio on the minimum-variance frontier."},{"t":"Capital allocation line (CAL)","f":"E[R_p] = R_f + \\left(\\dfrac{E(R_i) - R_f}{\\sigma_i}\\right)\\sigma_p","n":"Combinations of the risk-free asset and the optimal risky portfolio."}]},{"h":"Portfolio Risk & Return II","items":[{"t":"Capital market line (CML)","f":"E[R_p] = R_f + \\left(\\dfrac{E(R_m) - R_f}{\\sigma_m}\\right)\\sigma_p","n":"CAL where the risky portfolio is the market portfolio. Slope = market Sharpe ratio; left of M = lending, right of M = borrowing."},{"t":"Beta","f":"\\beta_i = \\dfrac{Cov(R_i, R_m)}{\\sigma_m^2} = \\dfrac{\\rho_{i,m}\\sigma_i}{\\sigma_m}","n":"Total risk = systematic (non-diversifiable/market) + nonsystematic (diversifiable) risk."},{"t":"Capital asset pricing model (CAPM)","f":"E[R_i] = R_f + \\beta_i[E(R_m) - R_f]","n":"Assumes risk-averse utility-maximizing investors, frictionless markets, single holding period, homogeneous expectations, infinitely divisible investments, price takers. Limitations: single-factor, single-period, includes non-investable assets."},{"t":"Security market line (SML)","n":"Graphical representation of CAPM: expected return vs. beta; slope = market risk premium E(R_m) − R_f; the market has β = 1."},{"t":"Identifying mispriced stocks","n":"Stocks plotting above the SML are underpriced (buy); stocks plotting below the SML are overpriced (sell)."}]},{"h":"Performance Ratios","items":[{"t":"Sharpe ratio","f":"\\text{Sharpe} = \\dfrac{R_p - R_f}{\\sigma_p}","n":"Total-risk measure (uses standard deviation)."},{"t":"M-squared","f":"M^2 = (R_p - R_f)\\dfrac{\\sigma_m}{\\sigma_p} + R_f"},{"t":"Treynor ratio","f":"\\text{Treynor} = \\dfrac{R_p - R_f}{\\beta_p}","n":"Systematic-risk measure (uses beta)."},{"t":"Jensen's alpha","f":"\\alpha_p = R_p - [R_f + \\beta_p(R_m - R_f)]"}]},{"h":"Portfolio Management Overview","items":[{"t":"Portfolio management process","n":"Planning: objectives & constraints in the IPS. Execution: asset allocation, security analysis, portfolio construction. Feedback: monitoring/rebalancing, performance measurement & reporting."},{"t":"Institutional investors","n":"DB pension: younger beneficiaries → longer horizon, higher risk tolerance. Endowments/foundations: long horizon, low liquidity needs, high risk tolerance. Banks: short horizon, high liquidity, very low risk tolerance. Insurers: short horizon (longer for life), low risk tolerance. Investment companies & SWFs: vary by mandate."},{"t":"Pooled investments","n":"Robo-advisors: serve mass-affluent, low fees, low barriers. Mutual funds: open-end (new investors, trade at NAV), closed-end (no new shares, premium/discount), no-load. ETFs: trade intraday, can be shorted/margined, trade near NAV, lower minimums."}]},{"h":"Behavioral Biases","items":[{"t":"Asset allocation types","n":"Strategic asset allocation: IPS-permissible weights consistent with long-term objectives. Tactical asset allocation: deliberate short-term deviations from policy weights based on return forecasts."},{"t":"Cognitive errors","n":"Conservatism, confirmation, representativeness, illusion of control, hindsight, anchoring & adjustment, mental accounting, framing, availability biases."},{"t":"Emotional biases","n":"Loss-aversion, overconfidence, self-control, status-quo, endowment, regret-aversion biases."}]},{"h":"Risk Management","items":[{"t":"Risk management framework","n":"Risk governance; risk identification & measurement; risk infrastructure; policies & processes; risk monitoring/mitigation/management; communication; strategic analysis/integration. Risk tolerance = which risks; risk budgeting = how risks are taken. Risk measures: SD, beta, duration, delta, gamma, VaR, CVaR."}]}]},{"id":"ethics","name":"Ethical & Professional Standards","sections":[{"h":"Standards of Professional Conduct","items":[{"t":"I. Professionalism","n":"I(A) Knowledge of the Law: obey the strictest applicable law; disassociate from illegal/unethical activity. I(B) Independence & Objectivity: no gifts that impair objectivity (client gifts may be OK if disclosed). I(C) Misrepresentation: cite sources, no plagiarism, correct errors. I(D) Misconduct: personal conduct that reflects on professional integrity."},{"t":"II. Integrity of Capital Markets","n":"II(A) Material Nonpublic Information: do not act on or cause others to act on MNPI; seek public dissemination. II(B) Market Manipulation: no actions that distort prices or volume; market making and legitimate strategies are allowed."},{"t":"III. Duties to Clients","n":"III(A) Loyalty, Prudence & Care: client interests first; disclose proxy-voting & soft-commission policies. III(B) Fair Dealing: treat all clients fairly; communicate recommendations simultaneously. III(C) Suitability: use an updated IPS; evaluate in portfolio context. III(D) Performance Presentation: fair, accurate, complete. III(E) Confidentiality: keep client info confidential unless illegal activity, legally required, or client permits."},{"t":"IV. Duties to Employers","n":"IV(A) Loyalty: get permission before competing outside work; abide by non-compete; don't take employer property. IV(B) Additional Compensation: written permission from all parties for outside compensation. IV(C) Responsibilities of Supervisors: adequately train and monitor subordinates (may be delegated)."},{"t":"V. Investment Analysis & Recommendations","n":"V(A) Diligence & Reasonable Basis: support actions with research and analysis. V(B) Communication with Clients: distinguish fact from opinion; make appropriate disclosures. V(C) Record Retention: keep records supporting decisions (7-year retention recommended)."},{"t":"VI. Conflicts of Interest","n":"VI(A) Disclosure of Conflicts: disclose prominently in plain language. VI(B) Priority of Transactions: client and employer transactions before your own beneficial accounts. VI(C) Referral Fees: disclose referral fees (including non-monetary) to clients and employer."},{"t":"VII. Responsibilities as a CFA Member/Candidate","n":"VII(A) Conduct in the CFA Program: don't share confidential exam information (opinions on CFAI policies are permissible). VII(B) Reference to CFA Institute/Designation/Program: don't misrepresent the meaning of membership, the designation, or candidacy."}]}]}];window.CFA_FORMULAS_TOTAL=321;